"""Render the frozen external benchmark without overstating its independence."""
import os,json,csv
from pathlib import Path
os.environ.setdefault('MPLCONFIGDIR','/tmp/medical-ai-mpl')
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from scipy.special import expit
from sklearn.metrics import roc_curve
ROOT=Path(__file__).resolve().parents[1]
def main():
    out=ROOT/'reports/external_chest224';s=json.loads((out/'summary.json').read_text());n=s['sampling'];rows=list(csv.DictReader((out/'results.csv').open()));p=np.load(out/'predictions.npz');v=s['primary']
    text=['# Externer Transfer des unveränderten 224px-Modells','',f"Primäre AUROC gegen No-finding-Kontrollen: **{v['point']:.3f} [{v['ci'][0]:.3f}; {v['ci'][1]:.3f}]**. Das ist ein NIH-abgeleiteter Transferbenchmark mit textbasierten Labels, keine klinische Validierung des 512px-Modells.",'','## Daten und Trennung','',f"Das offizielle ChestMNIST224-Testarchiv umfasst {n['total_test']:,} Bilder. Exakte 224px-Pixelduplikate werden durch den ersten Repräsentanten ersetzt; bei widersprüchlichen vollständigen Labelvektoren wird die gesamte Hashgruppe ausgeschlossen. Verblieben: {n['retained_after_dedup']:,} Bilder; {len(n['duplicate_pairs'])} Duplikatpaare, {len(n['conflicting_pixel_hashes'])} widersprüchliche Hashgruppen.",f"Alle {n['selected']['pneumonia']} verbleibenden Pneumonie-Label-positiven Bilder werden verwendet, darunter {n['positive_with_additional_tags']} mit zusätzlichen Labels. Mit festem Seed wurden {n['selected']['no_finding']} No-finding-Kontrollen und {n['selected']['other_abnormal']} Kontrollen mit anderen Labels ausgewählt, ohne Modellvorhersagen zu betrachten.",'','Das [Protokoll](../../configs/external_chest224.json) wurde vor Inferenz festgeschrieben. Der originale MobileNet224-Encoder und der bereits gelernte lineare Kopf bleiben unverändert. Die Rekonstruktion reproduziert 16 interne Referenzlogits. Native 224px-Eingaben werden direkt normalisiert; keine Hochskalierung als vermeintliche 512px-Information. Klassifikationsschwelle 0,5, Konfidenzschwelle aus der früheren internen Kalibrierung. Kein Training, keine externe Kalibrierung und keine Test-basierte Modellwahl.','','## Ergebnisse','','| Kontrollgruppe | AUROC [95 %] | Sensitivität | Spezifität | Accuracy | Fehler bei 80 % Abdeckung |','|---|---:|---:|---:|---:|---:|']
    for row in rows:
        a=s['results'][row['control']]['auroc'];text.append(f"| {row['control']} | {a['point']:.3f} [{a['ci'][0]:.3f}; {a['ci'][1]:.3f}] | {float(row['sensitivity'])*100:.1f} % | {float(row['specificity'])*100:.1f} % | {float(row['accuracy'])*100:.1f} % | {float(row['risk_at_80'])*100:.1f} % |")
    r=rows[0]
    text+=['',f"Bei der unveränderten internen Konfidenzschwelle werden im primären Vergleich {float(r['coverage'])*100:.1f} % der Fälle akzeptiert. Unter diesen liegt die Fehlerquote bei **{float(r['retained_error'])*100:.1f} %**, gegenüber {100*(1-float(r['accuracy'])):.1f} % über alle Fälle. Die interne Ablehnungsregel liefert auf dieser Stichprobe damit keine verlässliche Fehlerreduktion. Auch die mittlere Modellkonfidenz von {float(r['mean_confidence'])*100:.1f} % ist keine bestätigte individuelle Erkrankungswahrscheinlichkeit."]
    text+=['','![Externe ROC-Kurven und Ausgabeverteilungen](transfer.png)','','2.000 labelstratifizierte Bild-Bootstraps pro Vergleich, bei festem Modell. Patientenkennungen fehlen im NPZ: Abhängigkeiten mehrerer Aufnahmen können die Intervalle zu eng machen. Die Intervalle sind keine klinischen oder patientenvalidierten Unsicherheitsgrenzen. Alle weiteren Kennzahlen, insbesondere NLL und Abdeckung bei fester Konfidenzschwelle, stehen in [results.csv](results.csv).','','## Grenzen','','- No finding bedeutet einen vollständig leeren Textlabel-Vektor, nicht unabhängig bestätigte Gesundheit. Andere Erkrankungen und zusätzliche Pneumonie-Tags können sich überlagern.','- Extern gegenüber der Kermany-Trainingsquelle; NIH kann sich jedoch mit historischen RSNA-Projekttests überschneiden. Keine Behauptung vollständig neuer Patienten oder einer neuen unabhängigen Klinik.','- Labelqualität, Alters-/Patientenpopulation, Bildgeometrie und Quelle unterscheiden sich gleichzeitig; die Analyse isoliert keine Fehlerursache.','- Fallkontrollartige Stichprobe: Accuracy, NLL, Präzision und Akzeptanzfehler beschreiben diese Stichprobe, keine Zielpopulation.','- Native 224px-Daten prüfen den 224px-Ausgangspunkt. Die unabhängige klinische 512px-Prüfung bleibt offen.','','## Nachrechnung und Quellen','','[Stichprobe und Ausschlüsse](sampling.json), [Vorhersagen](predictions.npz), [Intervalle und Herkunft](summary.json), [unabhängige Kennzahlenprüfung](verification.json), [unabhängige Stichprobenprüfung](sampling_verification.json). Die Prüfer rekonstruieren alle 4.000 vollständigen Bootstrapziehungen sowie die Auswahl aus sämtlichen offiziellen Testbildern.','','```bash','python scripts/fetch_external_chest224.py','python experiments/external_chest224.py','python scripts/verify_external_chest224.py','python scripts/verify_external_chest224_sample.py','python scripts/report_external_chest224.py','python scripts/report_pipeline_transfer.py','```','','Der Erzeuger überschreibt keine vorhandene Ergebnisstudie; für Wiederholungen eine separate Arbeitskopie verwenden. [Zweiseitige Forschungsnotiz](research_note.pdf) verbindet diese Auswertung mit der [512px-Vorverarbeitungsanalyse](../original_512/preprocessing/README.md).','','Quelle: [offizielles Zenodo-Archiv](https://zenodo.org/records/10519652), MD5 `45bd33e6f06c3e8cdb481c74a89152aa`. Attribution: Yang et al., MedMNIST v2, Scientific Data (2023), doi:10.1038/s41597-022-01721-8; Wang et al., ChestX-ray8, CVPR (2017), NIH ChestX-ray14. Laut offizieller ChestMNIST-Metadatei CC BY 4.0; [Lizenz- und Zugangsprüfung](../../docs/LICENSING.md). Rohbilder bleiben lokal. Code und Analyse mit KI-Assistenz.']
    text += ['', '## Beschreibende Abdeckungsanalyse', '', '![Fehlerrate nach akzeptiertem Anteil](selective_coverage.png)\n\nZusätzliche Darstellung derselben gespeicherten Vorhersagen, kein neuer Modelltest oder Schwellen-Fit. 20 Abdeckungsstufen je Kontrollgruppe, mit anteiliger Gewichtung gleicher Konfidenzen an der Grenze. Orange: unveränderte interne Schwelle. Die Kurven haben keine Unsicherheitsbänder; Werte bei 80 %, vollständiger Abdeckung und fester Schwelle wurden gegen die bestehende Auswertung geprüft. [CSV](selective_coverage.csv) · [Prüfprotokoll](selective_coverage_verification.json). Erzeugung: `python scripts/plot_external_selective.py`.']
    (out/'README.md').write_text('\n'.join(text)+'\n')
    fig,axes=plt.subplots(1,2,figsize=(10,4),layout='constrained')
    for control in ['no_finding','other_abnormal']:
        m=(p['strata']=='pneumonia')|(p['strata']==control);fpr,tpr,_=roc_curve(p['labels'][m],expit(p['logits'][m]));axes[0].plot(fpr,tpr,label=control)
    axes[0].plot([0,1],[0,1],'--',color='gray');axes[0].set(xlabel='False positive rate',ylabel='True positive rate',title='Frozen 224px model');axes[0].legend(fontsize=8)
    for group in ['pneumonia','no_finding','other_abnormal']:
        axes[1].hist(p['logits'][p['strata']==group],bins=25,density=True,histtype='step',label=group,lw=1.5)
    axes[1].axvline(0,color='gray',ls='--');axes[1].set(xlabel='Pneumonia logit',ylabel='Density within label stratum',title='Weak external labels');axes[1].legend(fontsize=8)
    fig.savefig(out/'transfer.png',dpi=170);fig.savefig(out/'transfer.pdf');plt.close(fig)
if __name__=='__main__':main()
